def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds: The time in nanoseconds since midnight.
    :param tz: An optional timezone to use for the time.
    :return: A `datetime.time` object if `tz` is None, otherwise a `datetime.datetime` object.
    """
    if not isinstance(nanoseconds, int):
        raise ValueError("nanoseconds must be an integer")

    if nanoseconds < 0 or nanoseconds >= 86400000000000:
        raise ValueError("nanoseconds must be between 0 and 86399999999999 (inclusive)")

    seconds, nanos = divmod(nanoseconds, 1000000000)
    minutes, seconds = divmod(seconds, 60)
    hours, minutes = divmod(minutes, 60)

    if tz is None:
        return datetime.time(hour=hours, minute=minutes, second=seconds, microsecond=nanos // 1000)
    else:
        if not isinstance(tz, datetime.tzinfo):
            raise ValueError("tz must be an instance of datetime.tzinfo")
        return datetime.datetime(year=1, month=1, day=1, hour=hours, minute=minutes, second=seconds, microsecond=nanos // 1000, tzinfo=tz)

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if not isinstance(value, time):
        raise TypeError("Expected a time object, got {}".format(type(value).__name__))

    return value.isoformat()

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if not isinstance(value, Point):
        raise TypeError("Expected a Point instance, got {}".format(type(value).__name__))

    try:
        return {
            'x': value.x,
            'y': value.y
        }
    except AttributeError as e:
        raise ValueError("Point instance does not have the expected attributes: {}".format(e))

def keys(self):
