def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        def wrapper(tx, *args, **kwargs):
            if metadata is not None and not isinstance(metadata, dict):
                raise ValueError("Metadata must be a dictionary.")
            if timeout is not None and not isinstance(timeout, (int, float)):
                raise ValueError("Timeout must be a number.")
            if timeout is not None and timeout < 0:
                raise ValueError("Timeout must not be negative.")
            return func(tx, *args, **kwargs)
        wrapper._metadata = metadata
        wrapper._timeout = timeout
        return wrapper
    return decorator

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    if not hasattr(self, '_data'):
        raise AttributeError("Instance does not have an _data attribute")
    if not isinstance(self._data, (list, tuple)):
        raise TypeError("_data attribute must be a list or tuple")
    try:
        return self._data.index(key)
    except ValueError:
        raise KeyError(f"{key} is not in the list")

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    try:
        if not keys:
            return list(self._data.values())

        result = []
        for key in keys:
            if isinstance(key, int):
                result.append(self._data[list(self._data.keys())[key]])
            elif isinstance(key, str):
                result.append(self._data[key])
            else:
                raise ValueError(f"Invalid key type: {type(key)}. Expected int or str.")
        return result
    except (IndexError, KeyError) as e:
        raise KeyError(f"Key not found: {e}") from e
    except Exception as e:
        raise Exception(f"An error occurred: {e}") from e

def data(self, *keys):
    result = {}
    if not keys:
        return dict(zip(self._fields, self))

    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(self):
                raise IndexError(f"Index {key} is out of bounds")
            result[self._fields[key]] = self[key]
        elif isinstance(key, str):
            if key in self._fields:
                index = self._fields.index(key)
                result[key] = self[index]
            else:
                result[key] = None
        else:
            raise TypeError(f"Invalid key type: {type(key)}")

    return result

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
            hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """
    try:
        if not isinstance(n, int) or n < -1:
            raise ValueError("n must be an integer greater than or equal to -1")
        if not isinstance(qid, int) or qid < -1:
            raise ValueError("qid must be an integer greater than or equal to -1")
        if dehydration_hooks is not None and not isinstance(dehydration_hooks, dict):
            raise TypeError("dehydration_hooks must be a dictionary or None")
        if hydration_hooks is not None and not isinstance(hydration_hooks, dict):
            raise TypeError("hydration_hooks must be a dictionary or None")

        message = {
            "name": "DISCARD",
            "args": {
                "n": n,
                "qid": qid
            }
        }
        if dehydration_hooks:
            message["args"]["dehydration_hooks"] = dehydration_hooks
        if hydration_hooks:
            message["args"]["hydration_hooks"] = hydration_hooks
        if handlers:
            message["args"]["handlers"] = handlers

        self.output_queue.append(message)
    except Exception as e:
        raise RuntimeError(f"Failed to append DISCARD message to output queue: {e}")

def round_half_to_even(n):
