def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    if not isinstance(name, str) or not name:
        raise ValueError("Name must be a non-empty string.")
    if not isinstance(fields, dict):
        raise ValueError("Fields must be a dictionary.")
    if not isinstance(srid_map, dict):
        raise ValueError("SRID map must be a dictionary.")

    class Point:
        def __init__(self, **kwargs):
            for field, field_type in fields.items():
                if field not in kwargs:
                    raise ValueError(f"Missing required field: {field}")
                if not isinstance(kwargs[field], field_type):
                    raise ValueError(f"Field {field} must be of type {field_type.__name__}")
                setattr(self, field, kwargs[field])
            self.srid = srid_map.get('default', 4326)  # Default SRID is 4326 if not specified

        def __repr__(self):
            field_values = ', '.join(f"{field}={getattr(self, field)!r}" for field in fields)
            return f"{name}({field_values}, srid={self.srid})"

    Point.__name__ = name
    return Point

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            import warnings
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise ValueError("Input must be a string")

    try:
        # Split the string by '.' and convert each part to an integer
        version_parts = tuple(int(part) for part in s.split('.'))
    except ValueError:
        raise ValueError("Version string must contain only integers separated by dots")

    if not version_parts:
        raise ValueError("Version string cannot be empty")

    return version_parts

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    if not isinstance(cmd, tuple):
        raise TypeError("cmd must be a tuple")
    if not all(isinstance(arg, str) for arg in cmd):
        raise ValueError("All elements of cmd must be strings")

    import sys
    import os

    if sys.platform == "win32":
        # Check if the first element is a script with a shebang
        script_path = cmd[0]
        if os.path.isfile(script_path):
            with open(script_path, 'r', encoding='utf-8') as file:
                first_line = file.readline().strip()
                if first_line.startswith('#!'):
                    # Extract the interpreter from the shebang
                    interpreter = first_line[2:].split()[0]
                    # Replace the script path with the interpreter and the script path
                    cmd = (interpreter, script_path) + cmd[1:]

    return cmd

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            cache_key = key(*args, **kwargs)
            if lock:
                with lock:
                    if cache_key in cache:
                        return cache[cache_key]
                    result = func(*args, **kwargs)
                    cache[cache_key] = result
                    return result
            else:
                if cache_key in cache:
                    return cache[cache_key]
                result = func(*args, **kwargs)
                cache[cache_key] = result
                return result
        return wrapper
    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    if not hasattr(self, '_order'):
        raise AttributeError("This method requires the object to have an '_order' attribute.")
    if not self._order:
        raise KeyError("popitem(): dictionary is empty")
    key = self._order.pop(0)
    value = self.pop(key)
    return key, value

