def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    try:
        self.context = {}
        if hasattr(self, 'initial_value'):
            self.bins = {key: self.initial_value for key in self.bins}
        elif hasattr(self, 'make_bins'):
            self.bins = self.make_bins()
        else:
            raise AttributeError("Histogram object must have either 'initial_value' or 'make_bins' defined.")
    except Exception as e:
        raise RuntimeError(f"Failed to reset histogram: {e}")

def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    if not isinstance(separator, str):
        raise ValueError("Separator must be a string.")
    if header is not None and not isinstance(header, str):
        raise ValueError("Header must be a string or None.")

    lines = []
    if header is not None:
        lines.append(header)

    try:
        for point in self.points:
            if not isinstance(point, tuple) or len(point) != 2:
                raise ValueError("Each point must be a tuple of (coordinate, value).")
            coord, value = point
            if isinstance(coord, tuple):
                coord_str = separator.join(map(str, coord))
            else:
                coord_str = str(coord)
            if isinstance(value, tuple):
                value_str = separator.join(map(str, value))
            else:
                value_str = str(value)
            lines.append(f"{coord_str}{separator}{value_str}")
    except AttributeError:
        raise ValueError("Graph object must have a 'points' attribute.")

    return "\n".join(lines) + "\n"

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if not isinstance(coord_name, str):
        raise ValueError("coord_name must be a string")

    if not hasattr(self, 'coordinates'):
        raise AttributeError("Instance does not have a 'coordinates' attribute")

    if coord_name not in self.coordinates:
        raise KeyError(f"Coordinate '{coord_name}' not found in coordinates")

    if not hasattr(self, 'error_indices'):
        raise AttributeError("Instance does not have an 'error_indices' attribute")

    if coord_name not in self.error_indices:
        raise KeyError(f"Error indices for coordinate '{coord_name}' not found")

    return self.error_indices[coord_name]

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    if not isinstance(bins, (list, tuple)) or not isinstance(edges, (list, tuple)):
        raise ValueError("Both bins and edges must be lists or tuples.")
    if len(bins) != len(edges) - 1:
        raise ValueError("The number of bins must be one less than the number of edges.")
    if any(not isinstance(b, (int, float)) for b in bins):
        raise ValueError("All elements in bins must be numbers.")
    if any(not isinstance(e, (int, float)) for e in edges):
        raise ValueError("All elements in edges must be numbers.")
    if edges != sorted(edges):
        raise ValueError("Edges must be in non-decreasing order.")

    total = 0.0
    for i in range(len(bins)):
        width = edges[i + 1] - edges[i]
        total += bins[i] * width

    return total

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    if not isinstance(seq, (list, tuple)):
        raise ValueError("seq must be a list or tuple")

    def is_fill_request(element):
        # Assuming FillRequest is a specific type or class, replace 'FillRequest' with the actual type
        return isinstance(element, FillRequest)

    def is_source_sequence(element):
        # Assuming Source is a specific type or class, replace 'Source' with the actual type
        return isinstance(element, Source)

    if is_source_sequence(seq):
        return False

    if is_fill_request(seq):
        return True

    for element in seq:
        if is_source_sequence(element):
            return False
        if is_fill_request(element):
            return True

    return False

