def difference(d1, d2, level=-1):
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise ValueError("Both d1 and d2 must be dictionaries.")
    if not isinstance(level, int):
        raise ValueError("Level must be an integer.")

    def _difference(sub_d1, sub_d2, current_level):
        if current_level == 0:
            return sub_d1

        diff = {}
        for key in sub_d1:
            if key not in sub_d2:
                diff[key] = sub_d1[key]
            elif isinstance(sub_d1[key], dict) and isinstance(sub_d2[key], dict):
                nested_diff = _difference(sub_d1[key], sub_d2[key], current_level - 1)
                if nested_diff:
                    diff[key] = nested_diff
            elif sub_d1[key] != sub_d2[key]:
                diff[key] = sub_d1[key]
        return diff

    return _difference(d1, d2, level)

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    try:
        if not isinstance(coord, tuple):
            raise ValueError("Coordinate must be a tuple.")
        if not all(isinstance(c, int) for c in coord):
            raise ValueError("All elements of the coordinate must be integers.")
        if not isinstance(weight, (int, float)):
            raise ValueError("Weight must be a number.")

        if len(coord) != len(self.shape):
            raise ValueError("Coordinate dimensions must match histogram dimensions.")

        if all(0 <= c < s for c, s in zip(coord, self.shape)):
            self._data[coord] += weight
    except Exception as e:
        print(f"An error occurred: {e}")

def _validate_labels(labels):
    import re
    from collections.abc import Hashable

    class ValidationError(Exception):
        def __init__(self, messages):
            self.messages = messages
            super().__init__(f"Validation errors: {messages}")

    key_regex = re.compile(r'^[a-zA-Z0-9._-]+$')
    value_regex = re.compile(r'^[a-zA-Z0-9._-]+$')

    errors = []

    for key, value in labels.items():
        if not isinstance(key, Hashable):
            errors.append({str(key): 'expected hashable object'})
            continue

        key_str = str(key)
        if not key_regex.match(key_str):
            errors.append({key_str: f"Label key '{key_str}' does not match the regex '^[a-zA-Z0-9._-]+$'"})

        if not isinstance(value, (str, bytes)):
            errors.append({str(value): 'expected string or bytes-like object'})
            continue

        value_str = str(value)
        if not value_regex.match(value_str):
            errors.append({value_str: f"Label value '{value_str}' does not match the regex '^[a-zA-Z0-9._-]+$'"})


    if errors:
        raise ValidationError(errors)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    if not isinstance(manifest_dict, dict):
        raise ValueError("manifest_dict must be a dictionary")

    observer_schema = {}
    identifying_fields = {'apiVersion', 'kind', 'metadata'}

    for key, value in manifest_dict.items():
        if first_level and key in identifying_fields:
            observer_schema[key] = value
        elif isinstance(value, dict):
            observer_schema[key] = generate_default_observer_schema_dict(value)
        elif isinstance(value, list):
            observer_schema[key] = [generate_default_observer_schema_dict(item) if isinstance(item, dict) else None for item in value]
        else:
            observer_schema[key] = None

    return observer_schema

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    if not app or not hasattr(app, 'spec') or not hasattr(app.spec, 'manifest'):
        raise ValueError("Invalid application object or missing manifest")

    if not isinstance(app.spec.manifest, dict):
        raise ValueError("Manifest must be a dictionary")

    default_schema = {}
    for resource_type, resources in app.spec.manifest.items():
        if not isinstance(resources, list):
            raise ValueError(f"Resources for {resource_type} must be a list")

        for resource in resources:
            if not isinstance(resource, dict) or 'metadata' not in resource:
                raise ValueError(f"Invalid resource format for {resource_type}")

            resource_name = resource['metadata'].get('name')
            if not resource_name:
                raise ValueError(f"Resource of type {resource_type} must have a name")

            if resource_type not in default_schema:
                default_schema[resource_type] = {}

            if resource_name not in default_schema[resource_type]:
                default_schema[resource_type][resource_name] = {
                    "status": {
                        "type": "object",
                        "properties": {
                            "conditions": {
                                "type": "array",
                                "items": {
                                    "type": "object",
                                    "properties": {
                                        "type": {"type": "string"},
                                        "status": {"type": "string"},
                                        "lastProbeTime": {"type": "string"},
                                        "lastTransitionTime": {"type": "string"},
                                        "reason": {"type": "string"},
                                        "message": {"type": "string"}
                                    },
                                    "required": ["type", "status"]
                                }
                            }
                        }
                    }
                }

    return default_schema

