    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
        :class:`list`).
    """
    if not isinstance(sql, (str, bytes)):
        raise ValueError("sql must be a string or bytes")

    if not isinstance(params, (dict, list, tuple)):
        raise ValueError("params must be a dict, list, or tuple")

    in_style = getattr(self, 'SQLParams', None) and getattr(self.SQLParams, 'in_style', None)
    out_style = getattr(self, 'SQLParams', None) and getattr(self.SQLParams, 'out_style', None)

    if in_style is None or out_style is None:
        raise AttributeError("SQLParams.in_style and SQLParams.out_style must be defined")

    if in_style == 'named' and not isinstance(params, dict):
        raise ValueError("params must be a dict for named parameter style")
    if in_style == 'ordinal' and not isinstance(params, (list, tuple)):
        raise ValueError("params must be a list or tuple for ordinal parameter style")

    if out_style == 'named':
        if in_style == 'named':
            return sql, params.copy()
        elif in_style == 'ordinal':
            param_dict = {f":{i+1}": param for i, param in enumerate(params)}
            formatted_sql = sql
            for i, param in enumerate(params):
                placeholder = f"%({i+1})s"
                formatted_sql = formatted_sql.replace(placeholder, f":{i+1}")
            return formatted_sql, param_dict

    elif out_style == 'ordinal':
        if in_style == 'named':
            param_list = [params[key] for key in sorted(params.keys(), key=lambda x: int(x.lstrip(':')))]
            formatted_sql = sql
            for key in sorted(params.keys(), key=lambda x: int(x.lstrip(':'))):
                formatted_sql = formatted_sql.replace(key, f"%({int(key.lstrip(':'))})s")
            return formatted_sql, param_list
        elif in_style == 'ordinal':
            return sql, params.copy()

    raise ValueError("Unsupported parameter style conversion")

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    if not isinstance(prefix, str):
        raise ValueError("Prefix must be a string.")
    try:
        status = self.get_status()  # Assuming there's a method to get the status
    except AttributeError:
        raise AttributeError("The object does not have a 'get_status' method.")
    except Exception as e:
        raise Exception(f"An error occurred while retrieving the status: {e}")

    if not isinstance(status, str):
        raise ValueError("Status must be a string.")

    return f"{prefix}{status}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    if not isinstance(prefix, str):
        raise ValueError("Prefix must be a string.")

    try:
        # Assuming self.validation_log is the attribute holding the log data
        log_str = '\n'.join(self.validation_log)
    except AttributeError:
        raise AttributeError("Object has no attribute 'validation_log'.")
    except Exception as e:
