def validate(self, inventory, extract_spec_version=False):
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary.")

    if extract_spec_version:
        type_value = inventory.get('type')
        if type_value == 'specification_v1':
            self.spec_version = '1.0'
        elif type_value == 'specification_v2':
            self.spec_version = '2.0'
        else:
            # If type value is not valid or not present, use the version from self.spec_version
            if not hasattr(self, 'spec_version') or not self.spec_version:
                raise ValueError("Specification version not found in inventory or instance.")

    # Additional validation logic can be added here based on self.spec_version
    # For now, we'll just check if the inventory has a 'name' key as an example
    if 'name' not in inventory:
        raise ValueError("Inventory must contain a 'name' key.")

    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if not isinstance(manifest_files, dict):
        raise ValueError("manifest_files must be a dictionary.")
    if not isinstance(digests_used, set):
        raise ValueError("digests_used must be a set.")

    all_digests = set()
    for file_data in manifest_files.values():
        if not isinstance(file_data, dict) or 'digest' not in file_data:
            raise ValueError("Each entry in manifest_files must be a dictionary containing a 'digest' key.")
        all_digests.add(file_data['digest'])

    missing_digests = all_digests - digests_used
    if missing_digests:
        raise ValueError(f"Digests present in manifest but not used: {missing_digests}")

    return True

def validate_as_prior_version(self, prior):
    if not isinstance(prior, InventoryValidator):
        raise TypeError("The prior argument must be an instance of InventoryValidator.")

    if not hasattr(self, 'inventory') or not hasattr(prior, 'inventory'):
        raise AttributeError("Both self and prior must have an 'inventory' attribute.")

    # Assuming inventory is a dictionary where keys are item names and values are quantities
    for item, quantity in self.inventory.items():
        if item in prior.inventory:
            if prior.inventory[item] > quantity:
                raise ValueError(f"Item '{item}' has a higher quantity in the prior version than the current version.")
        else:
            raise ValueError(f"Item '{item}' is present in the current version but not in the prior version.")

    # Check for items in the prior that are not in the current version
    for item in prior.inventory:
        if item not in self.inventory:
            raise ValueError(f"Item '{item}' is present in the prior version but not in the current version.")

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary.")
    if not isinstance(version, str):
        raise ValueError("Version must be a string.")

    if version not in inventory:
        raise KeyError(f"Version {version} not found in inventory.")

    logical_path_map = {}

    for logical_path, details in inventory.get(version, {}).items():
        if not isinstance(details, dict) or 'files' not in details:
            raise ValueError(f"Invalid entry for {logical_path} in version {version}.")

        files = details.get('files', [])
        if not isinstance(files, list):
            raise ValueError(f"Files for {logical_path} in version {version} must be a list.")

        logical_path_map[logical_path] = set(files)

    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary.")

    if not isinstance(manifest_files, list):
        raise ValueError("Manifest files must be a list.")

    for file_name in fixity:
        if file_name not in manifest_files:
            raise ValueError(f"File '{file_name}' in fixity block is not listed in the manifest.")

        file_info = fixity[file_name]
        if not isinstance(file_info, dict):
            raise ValueError(f"File info for '{file_name}' must be a dictionary.")

        if 'algorithm' not in file_info or 'value' not in file_info:
            raise ValueError(f"File info for '{file_name}' must contain 'algorithm' and 'value' keys.")

        if not isinstance(file_info['algorithm'], str) or not isinstance(file_info['value'], str):
            raise ValueError(f"Algorithm and value for '{file_name}' must be strings.")

def files_list(path):
    """
    Return the files in `path`
    """
    import os

    if not isinstance(path, str):
        raise ValueError("The path must be a string.")

    if not os.path.exists(path):
        raise FileNotFoundError(f"The path {path} does not exist.")

    if not os.path.isdir(path):
        raise NotADirectoryError(f"The path {path} is not a directory.")

    try:
        return [f for f in os.listdir(path) if os.path.isfile(os.path.join(path, f))]
    except Exception as e:
        raise RuntimeError(f"An error occurred while listing files in {path}: {e}")

def add_rendition(self, lang, file_path):
    if not isinstance(lang, str) or not isinstance(file_path, str):
        raise ValueError("Both lang and file_path must be strings.")
    if not lang:
        raise ValueError("Language code (lang) cannot be an empty string.")
    if not file_path:
        raise ValueError("File path (file_path) cannot be an empty string.")

    if not hasattr(self, 'renditions'):
        self.renditions = {}

    if lang in self.renditions:
        raise KeyError(f"A rendition for language '{lang}' already exists.")

    self.renditions[lang] = file_path

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`
    """
    if not isinstance(content, str):
        raise ValueError("Input content must be a string.")

    try:
        fixed_content = content.replace('w:st="', 'w-st="')
    except Exception as e:
        raise RuntimeError(f"An error occurred while processing the content: {e}")

