def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    if not node or not pubdate_xpaths:
        raise ValueError("Both node and pubdate_xpaths must be provided.")

    if not isinstance(pubdate_xpaths, list):
        raise TypeError("pubdate_xpaths must be a list of XPath expressions.")

    for xpath in pubdate_xpaths:
        if not isinstance(xpath, str):
            raise ValueError("Each XPath expression in pubdate_xpaths must be a string.")

        try:
            result = node.xpath(xpath)
            if result:
                return result[0]
        except Exception as e:
            raise RuntimeError(f"Error evaluating XPath '{xpath}': {e}")

    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    try:
        indent_str = ' ' * indent
        if debug:
            return f"{indent_str}<Debug: {self.__class__.__name__} at {hex(id(self))}>"
        else:
            return f"{indent_str}{self.__class__.__name__}()"
    except Exception as e:
        return f"{indent_str}<Error: {str(e)}>"

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    if not isinstance(args, list):
        raise ValueError("args must be a list of expressions")

    def apply_absorption(expr):
        if not isinstance(expr, tuple) or len(expr) != 3:
            return expr

        op, left, right = expr

        if op == '&':
            if right == (('|', left, '_')):
                return left
            if right == (('&', ('~', left), '_')):
                return ('&', left, right[2])
        elif op == '|':
            if right == (('&', left, '_')):
                return left
            if right == (('|', ('~', left), '_')):
                return ('|', left, right[2])

        return expr

    return [apply_absorption(arg) for arg in args]

def base_config(user, etcd_host="localhost", etcd_port=2379):
    """Creates a configuration with some simple parameters, which have a default value
    that can be set.

    Args:
        user (str): the name of the user for the static authentication
        etcd_host (str): the host for the database.
        etcd_port (int): the port for the database.

    Returns:
        dict: the created configuration.

    """
    if not isinstance(user, str):
        raise ValueError("user must be a string")
    if not isinstance(etcd_host, str):
        raise ValueError("etcd_host must be a string")
    if not isinstance(etcd_port, int):
        raise ValueError("etcd_port must be an integer")
    if etcd_port <= 0 or etcd_port > 65535:
        raise ValueError("etcd_port must be a valid port number between 1 and 65535")

    return {
        "user": user,
        "etcd_host": etcd_host,
        "etcd_port": etcd_port
    }

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    try:
        # Call the provided function to get the timezone names
        tz_names = namefunc()

        # Check if the output is a tuple of two elements
        if not isinstance(tz_names, tuple) or len(tz_names) != 2:
            raise ValueError("The function must return a tuple of two elements.")

        # Convert each element to a bytestring if it's a unicode string
        return tuple(name.encode('utf-8') if isinstance(name, unicode) else name for name in tz_names)

    except Exception as e:
        # Handle any exceptions that occur during the process
        raise RuntimeError("An error occurred while processing the timezone names: {}".format(e))

