def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if not isinstance(pieces, list):
        raise ValueError("pieces must be a list")
    if not all(isinstance(piece, str) for piece in pieces):
        raise ValueError("all elements in pieces must be strings")
    if not isinstance(style, str):
        raise ValueError("style must be a string")

    if style == "semver":
        return ".".join(pieces)
    elif style == "dotted":
        return ".".join(pieces)
    elif style == "hyphenated":
        return "-".join(pieces)
    elif style == "underscored":
        return "_".join(pieces)
    else:
        raise ValueError(f"unsupported style: {style}")

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    if not isinstance(pieces, list):
        raise ValueError("Input must be a list.")
    if '+' in pieces:
        return '.'
    else:
        return '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    if not isinstance(commands, (list, tuple)):
        raise ValueError("commands must be a list or tuple of command strings.")
    if not all(isinstance(cmd, str) for cmd in commands):
        raise ValueError("Each command in commands must be a string.")
    if not isinstance(args, (list, tuple)):
        raise ValueError("args must be a list or tuple of argument strings.")
    if not all(isinstance(arg, str) for arg in args):
        raise ValueError("Each argument in args must be a string.")
    if cwd is not None and not isinstance(cwd, str):
        raise ValueError("cwd must be a string or None.")
    if not isinstance(verbose, bool):
        raise ValueError("verbose must be a boolean.")
    if not isinstance(hide_stderr, bool):
        raise ValueError("hide_stderr must be a boolean.")
    if env is not None and not isinstance(env, dict):
        raise ValueError("env must be a dictionary or None.")

    full_command = list(commands) + list(args)
    try:
        if verbose:
            print(f"Running command: {' '.join(full_command)}")

        with subprocess.Popen(
            full_command,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE if hide_stderr else subprocess.STDOUT,
            text=True
        ) as process:
            output, errors = process.communicate()

        if process.returncode != 0:
            raise subprocess.CalledProcessError(process.returncode, full_command, output=output, stderr=errors)

        return output

    except FileNotFoundError as e:
        raise FileNotFoundError(f"Command not found: {full_command[0]}") from e
    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Command failed with return code {e.returncode}: {e.stderr}")
        raise
    except Exception as e:
        raise RuntimeError(f"An error occurred while running the command: {e}") from e

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    if not isinstance(vcs, str):
        raise ValueError("VCS must be a string.")
    if not callable(method):
        raise ValueError("Method must be callable.")

    def decorator(func):
        if not hasattr(func, 'vcs_handlers'):
            func.vcs_handlers = {}
        func.vcs_handlers[vcs] = method
        return func

    return decorator

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0

    try:
        # Assuming self.root is the starting point of the hierarchy
        for obj in self.root.iterate_objects():
            num_objects += 1
            is_valid = True

            if validate_objects:
                if not obj.is_valid():
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: Object {obj.id} is not valid.")

            if check_digests:
                if not obj.check_digest():
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: Digest mismatch for object {obj.id}.")

            if is_valid:
                good_objects += 1

    except AttributeError as e:
        print(f"AttributeError: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")

    return num_objects, good_objects

