def deep_merge_nodes(nodes):
    from ruamel.yaml.nodes import MappingNode, ScalarNode

    def merge_values(key, value1, value2):
        if isinstance(value1, MappingNode) and isinstance(value2, MappingNode):
            merged_value = value1.value.copy()
            for k2, v2 in value2.value:
                found = False
                for i, (k1, v1) in enumerate(merged_value):
                    if k1.value == k2.value:
                        merged_value[i] = (k2, merge_values(k2, v1, v2))
                        found = True
                        break
                if not found:
                    merged_value.append((k2, v2))
            return MappingNode(tag=value1.tag, value=merged_value)
        else:
            return value2

    merged_dict = {}
    for key, value in nodes:
        if key.value in merged_dict:
            merged_dict[key.value] = merge_values(key, merged_dict[key.value], value)
        else:
            merged_dict[key.value] = value

    return [(ScalarNode(tag=key.tag, value=key_value), value) for key_value, value in merged_dict.items()]

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    try:
        flags = []
        for action in parser._actions:
            if action.option_strings:
                flags.extend(action.option_strings)
        return ' '.join(flags)
    except AttributeError as e:
        raise ValueError("The provided object is not an instance of argparse.ArgumentParser") from e

def parse_subparser_arguments(unparsed_arguments, subparsers):
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise ValueError("unparsed_arguments must be a list or tuple")
    if not isinstance(subparsers, dict):
        raise ValueError("subparsers must be a dictionary")
    if not all(isinstance(parser, argparse.ArgumentParser) for parser in subparsers.values()):
        raise ValueError("All values in subparsers must be argparse.ArgumentParser instances")

    parsed_results = {}
    remaining_arguments = list(unparsed_arguments)

    for subparser_name, parser in subparsers.items():
        try:
            # Attempt to parse the arguments using the current subparser
            parsed_namespace, remaining = parser.parse_known_args(remaining_arguments)
            parsed_results[subparser_name] = parsed_namespace
            remaining_arguments = remaining
        except Exception as e:
            # If parsing fails, log the error and continue with the next subparser
            print(f"Failed to parse arguments for subparser '{subparser_name}': {e}")

    return parsed_results, remaining_arguments

