def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if not isinstance(dicts, (list, tuple)):
        raise TypeError("The input must be a list or tuple of dictionaries.")

    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise ValueError("All elements of the input iterable must be dictionaries.")
        for key, value in d.items():
            if not isinstance(value, (int, float)):
                raise ValueError("All dictionary values must be numbers.")
            if key in result:
                result[key] += value
            else:
                result[key] = value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not isinstance(url, str):
        raise ValueError("The url parameter must be a string.")
    if not isinstance(url_args, dict):
        raise ValueError("The url_args parameter must be a dictionary.")

    try:
        for key, value in url_args.items():
            placeholder = f"{{{key}}}"
            if placeholder in url:
                url = url.replace(placeholder, str(value))
        return url
    except Exception as e:
        raise RuntimeError(f"An error occurred while replacing URL arguments: {e}")

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    if isinstance(val, str):
        return val.strip().lower() in {'none', 'null', 'nil', 'n/a', ''}
    return False

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    try:
        flags = []
        for action in parser._actions:
            if action.option_strings:
                flags.extend(action.option_strings)
        return ' '.join(flags)
    except AttributeError as e:
        raise ValueError("The provided object is not an instance of argparse.ArgumentParser") from e

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not isinstance(number, int) or number < 0:
        raise ValueError("Number must be a non-negative integer.")
    if not isinstance(alphabet, list) or not all(isinstance(char, str) and len(char) == 1 for char in alphabet):
        raise ValueError("Alphabet must be a list of single-character strings.")
    if padding is not None and (not isinstance(padding, int) or padding < 0):
        raise ValueError("Padding must be a non-negative integer or None.")

    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two characters.")

    if number == 0:
        return alphabet[0] * (padding if padding is not None else 1)

    digits = []
    while number:
        digits.append(alphabet[number % base])
        number //= base

    result = ''.join(reversed(digits))
    if padding is not None:
        result = result.rjust(padding, alphabet[0])

    return result

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    if not isinstance(flow_params, dict):
        raise ValueError("flow_params must be a dictionary")
    if not isinstance(register_number, int):
        raise ValueError("register_number must be an integer")
    if not isinstance(register_value, str):
        raise ValueError("register_value must be a string")

    for key, value in flow_params.items():
        if isinstance(value, dict):
            _replace_register(value, register_number, register_value)
        elif value == register_value:
            flow_params[key] = register_number

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise ValueError("The 'value' parameter must be a string.")
    if not isinstance(arg, str):
        raise ValueError("The 'arg' parameter must be a string.")

    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError("Input must be a class")

    subclasses_list = []

    def _get_subclasses(current_class):
        nonlocal subclasses_list
        subclasses_list.extend(current_class.__subclasses__())
        for subclass in current_class.__subclasses__():
            _get_subclasses(subclass)

    _get_subclasses(cls)
    return subclasses_list

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not isinstance(string, str):
        raise ValueError("Input string must be a string.")
    if not isinstance(alphabet, list) or not all(isinstance(char, str) for char in alphabet):
        raise ValueError("Alphabet must be a list of strings.")
    if len(alphabet) == 0:
        raise ValueError("Alphabet list cannot be empty.")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("Alphabet list must contain unique characters.")

    base = len(alphabet)
    result = 0
    for char in string:
        if char not in alphabet:
            raise ValueError(f"Character '{char}' in string is not in the alphabet.")
        digit_value = alphabet.index(char)
        result = result * base + digit_value
    return result

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True if macOS
    :rtype: bool
    """
    try:
        return os.name == 'posix' and 'darwin' in os.uname()
    except AttributeError:
