def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise ValueError("Input must be a string")

    # Remove leading and trailing single or double quotes
    return re.sub(r'^["\']|["\']$', '', name)

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re
    import sys

    if platform == 'this':
        platform = 1 if sys.platform != 'win32' else 0

    if platform == 1:  # POSIX
        # Regex for POSIX shell-like syntax
        regex = r"""(['"])(?:(?=(\\?))\2.)*?\1|\S+"""
    elif platform == 0:  # Windows/CMD
        # Regex for Windows CMD-like syntax
        regex = r"""(["'])(?:(?=(\\?))\2.)*?\1|\S+"""
    else:
        raise ValueError("Unsupported platform value. Use 'this', 1, or 0.")

    try:
        # Find all matches according to the regex
        return re.findall(regex, s, re.UNICODE)
    except TypeError:
        raise TypeError("Input must be a string.")
    except Exception as e:
        raise RuntimeError(f"An error occurred during splitting: {e}")

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None

    try:
        parts = frequency.split()
        if len(parts) != 2:
            raise ValueError("Frequency must be in the format 'number unit'")

        number = int(parts[0])
        unit = parts[1].lower()

        if unit in ['second', 'seconds']:
            return datetime.timedelta(seconds=number)
        elif unit in ['minute', 'minutes']:
            return datetime.timedelta(minutes=number)
        elif unit in ['hour', 'hours']:
            return datetime.timedelta(hours=number)
        elif unit in ['day', 'days']:
            return datetime.timedelta(days=number)
        elif unit in ['week', 'weeks']:
            return datetime.timedelta(weeks=number)
        else:
            raise ValueError(f"Unknown time unit: {unit}")

    except (ValueError, TypeError) as e:
        raise ValueError(f"Invalid frequency format: {frequency}") from e

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    if not isinstance(pattern, str):
        raise ValueError("The pattern must be a string.")

    if strip:
        pattern = pattern.strip()

    try:
        regex_pattern = re.compile(pattern)
    except re.error as e:
        raise ValueError(f"Invalid regex pattern: {e}")

    return regex_pattern

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list) or not all(isinstance(cmd, str) for cmd in commands):
        raise ValueError("commands must be a list of strings")
    if not isinstance(args, list) or not all(isinstance(arg, str) for arg in args):
        raise ValueError("args must be a list of strings")
    if cwd is not None and not isinstance(cwd, str):
        raise ValueError("cwd must be a string or None")
    if not isinstance(verbose, bool):
        raise ValueError("verbose must be a boolean")
    if not isinstance(hide_stderr, bool):
        raise ValueError("hide_stderr must be a boolean")
    if env is not None and not isinstance(env, dict):
        raise ValueError("env must be a dictionary or None")

    full_command = commands + args
    try:
        if verbose:
            print(f"Running command: {' '.join(full_command)}")
        result = subprocess.run(
            full_command,
            cwd=cwd,
            env=env,
            capture_output=True,
            text=True,
            stderr=subprocess.DEVNULL if hide_stderr else subprocess.PIPE
        )
        if verbose:
            print(f"Command output: {result.stdout}")
            if result.stderr:
                print(f"Command error: {result.stderr}")
        result.check_returncode()
        return result.stdout
    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Command failed with return code {e.returncode}: {e.stderr}")
        raise
    except Exception as e:
        if verbose:
            print(f"An error occurred: {e}")
        raise

def is_ipv4(target):
