def scale(self, other=None, recompute=False):
    if other is None:
        if not hasattr(self, '_scale') or recompute:
            self._scale = self._compute_scale()
        return self._scale
    elif isinstance(other, float):
        if self._scale == 0:
            raise LenaValueError("Histograms with scale equal to zero can't be rescaled.")
        self._scale = other
    else:
        raise TypeError("other must be None or a float")

def scale(self, other=None):
    if other is None:
        if self._scale is None or self._scale == 0:
            raise LenaValueError("Graph has unknown or zero scale.")
        return self._scale

    if not isinstance(other, (int, float)):
        raise TypeError("Scale must be a numeric value.")

    if self._scale is None or self._scale == 0:
        raise LenaValueError("Graph has unknown or zero scale, cannot rescale.")

    scale_factor = other / self._scale
    self._scale = other

    # Assuming self._data is a list of tuples representing coordinates
    # and errors, and the last element of each tuple is the coordinate
    # to be rescaled.
    self._data = [
        tuple(
            val * scale_factor if i == len(coord) - 1 else val
            for i, val in enumerate(coord)
        )
        for coord in self._data
    ]

    return self._scale

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if not hist:
        raise ValueError("Histogram is empty or not provided.")

    if make_value is None:
        make_value = lambda bin_: bin_

    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'.")

    if len(field_names) != 2 + (1 if isinstance(make_value(bin_), tuple) else 0):
        raise ValueError("Number of field_names must match the dimension of the result.")

    graph_points = []

    for bin_ in hist:
        if not isinstance(bin_, tuple) or len(bin_) != 2:
            raise ValueError("Each bin in the histogram must be a tuple of (coordinate, content).")

        coord, content = bin_
        if not isinstance(coord, (int, float)) or not isinstance(content, (int, float, tuple)):
            raise ValueError("Bin coordinate must be numeric and content must be numeric or a tuple.")

        if get_coordinate == "left":
            x = coord
        elif get_coordinate == "right":
            x = coord + 1
        elif get_coordinate == "middle":
            x = coord + 0.5

        y_values = make_value(content)
        if not isinstance(y_values, tuple):
            y_values = (y_values,)

        point = (x,) + y_values
        graph_points.append(point)

    graph_scale = scale
    if scale is True:
        graph_scale = hist.scale if hasattr(hist, 'scale') else None

    return {
        "points": graph_points,
        "field_names": field_names,
        "scale": graph_scale
    }

def _verify(iface, candidate, tentative=False, vtype=None):
    from zope.interface import Invalid, providedBy
    import inspect

    errors = []

    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"Candidate does not provide the interface {iface}")

    required_methods = set(iface.names(all=True, methods=True))
    required_attributes = set(iface.names(all=True, attributes=True)) - required_methods

    candidate_methods = set(dir(candidate))
    candidate_attributes = {name for name in candidate_methods if not callable(getattr(candidate, name))}

    missing_methods = required_methods - candidate_methods
    missing_attributes = required_attributes - candidate_attributes

    for method_name in missing_methods:
        errors.append(f"Missing method: {method_name}")

    for attr_name in missing_attributes:
        errors.append(f"Missing attribute: {attr_name}")

    for method_name in required_methods.intersection(candidate_methods):
        method = getattr(candidate, method_name)
        if not callable(method):
            errors.append(f"Expected method {method_name} to be callable, but it is not")
            continue

        iface_method = iface.get(method_name)
        if iface_method is None:
            continue

        iface_method_signature = inspect.signature(iface_method)
        candidate_method_signature = inspect.signature(method)

        if iface_method_signature != candidate_method_signature:
            errors.append(f"Method {method_name} has incorrect signature. Expected: {iface_method_signature}, Got: {candidate_method_signature}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

def verifyObject(iface, candidate, tentative=False):
    from zope.interface.exceptions import Invalid
    from zope.interface.verify import verifyObject as zope_verifyObject
    from zope.interface.verify import verifyClass
    from inspect import signature
    import zope.interface

    errors = []

    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"Candidate does not claim to provide the interface {iface}")

    # Check methods
    for name in iface.names(all=True):
        if iface.get(name).queryTaggedValue('interface.method') is not None:
            if not hasattr(candidate, name):
                errors.append(f"Missing method: {name}")
            else:
                method = getattr(candidate, name)
                if not callable(method):
                    errors.append(f"Attribute {name} is not callable")
                else:
                    iface_method = iface.get(name)
                    try:
                        sig = signature(method)
                        iface_sig = signature(iface_method)
                        if not sig.parameters.keys() == iface_sig.parameters.keys():
                            errors.append(f"Method {name} has incorrect signature: {sig} != {iface_sig}")
                    except ValueError:
                        errors.append(f"Could not compare signatures for method {name}")

    # Check attributes
    for name in iface.names(all=True):
        if iface.get(name).queryTaggedValue('interface.attribute') is not None:
            if not hasattr(candidate, name):
                errors.append(f"Missing attribute: {name}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(iface, type):
        raise TypeError("iface must be a class type")
    if not isinstance(candidate, type):
        raise TypeError("candidate must be a class type")

    try:
        if tentative:
            # Check if candidate is a subclass of iface
            return issubclass(candidate, iface)
        else:
            # Check if candidate is a subclass of iface and has all the methods of iface
            return issubclass(candidate, iface) and all(hasattr(candidate, attr) for attr in dir(iface) if callable(getattr(iface, attr)))
    except Exception as e:
        raise RuntimeError(f"An error occurred during verification: {e}")

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if not bases:
        raise ValueError("At least one base class must be provided")

    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("explicit_mc must be a type")
        return explicit_mc

    metaclasses = set()
    for base in bases:
        if not isinstance(base, type):
            raise TypeError("All bases must be types")
        metaclass = type(base)
        metaclasses.add(metaclass)

    if len(metaclasses) == 1:
        return metaclasses.pop()

    # If there are multiple metaclasses, find a common metaclass
    common_metaclass = None
    for m in metaclasses:
        if all(issubclass(c, m) for c in metaclasses):
            if common_metaclass is None or issubclass(m, common_metaclass):
                common_metaclass = m

    if common_metaclass is not None:
        return common_metaclass

    raise TypeError("Metaclass conflict: the metaclasses %s are incompatible" % ", ".join(repr(m) for m in metaclasses))

def pop(self, key, default=__marker):
    if key in self:
        value = self[key]
        del self[key]
        return value
    elif default is not __marker:
        return default
    else:
        raise KeyError(key)

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    if not hasattr(self, '_order'):
        raise AttributeError("This method requires an '_order' attribute to track usage order.")
    if not self._order:
        raise KeyError("popitem(): dictionary is empty")
    key = self._order.pop()
    value = self.pop(key)
    return key, value

def _create_converter(self) -> _converting._Converter:
    try:
        return _converting._Converter()
    except Exception as e:
        raise RuntimeError("Failed to create parameter style converter") from e

def isoparse(self, dt_str):
    from datetime import datetime
    from dateutil import parser, tz

    if not isinstance(dt_str, str):
        raise ValueError("Input must be a string")

    try:
        # Use dateutil's parser to parse the ISO 8601 string
        parsed_dt = parser.isoparse(dt_str)
    except ValueError as e:
        raise ValueError(f"Invalid ISO 8601 string: {dt_str}") from e

    # Ensure the parsed datetime is timezone-aware
    if parsed_dt.tzinfo is None:
        parsed_dt = parsed_dt.replace(tzinfo=tz.tzutc())

    return parsed_dt

def parse(self, timestr, default=None,
          ignoretz=False, tzinfos=None, **kwargs):
    if not isinstance(timestr, str):
        raise TypeError("Input must be a string")

    try:
        from dateutil import parser
        from dateutil.tz import tzoffset, tzfile, gettz

        if ignoretz:
            return parser.parse(timestr, default=default, ignoretz=ignoretz, **kwargs)

        if tzinfos is not None:
            if isinstance(tzinfos, dict):
                for tzname, tzinfo in tzinfos.items():
                    if isinstance(tzinfo, int):
                        tzinfos[tzname] = tzoffset(tzname, tzinfo)
                    elif isinstance(tzinfo, str):
                        tzinfos[tzname] = gettz(tzinfo)
            elif not callable(tzinfos):
                raise ValueError("tzinfos must be a dictionary or a callable")

        return parser.parse(timestr, default=default, tzinfos=tzinfos, **kwargs)

    except parser.ParserError as e:
        raise parser.ParserError(f"Error parsing date: {e}")
    except OverflowError as e:
        raise OverflowError(f"Date exceeds the largest valid C integer: {e}")
    except Exception as e:
        raise Exception(f"An unexpected error occurred: {e}")

def fromutc(self, dt):
    if not isinstance(dt, datetime.datetime):
        raise TypeError("dt must be a datetime.datetime object")
    if dt.tzinfo is None:
        raise ValueError("dt must be timezone-aware")

    # Convert the given UTC datetime to the timezone of self
    local_dt = dt.astimezone(self)

    # Check if the local datetime is in a fold state
    fold = 0
    if self.localize(local_dt.replace(fold=1), is_dst=None) == local_dt:
        fold = 1

    return local_dt.replace(fold=fold)

def default_tzinfo(dt, tzinfo):
    if not isinstance(dt, datetime.datetime):
        raise TypeError("The first argument must be an instance of datetime.datetime.")
    if not isinstance(tzinfo, datetime.tzinfo):
        raise TypeError("The second argument must be an instance of datetime.tzinfo.")

    if dt.tzinfo is None:
        return dt.replace(tzinfo=tzinfo)
    else:
        return dt

