def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("spec_content is None")

    try:
        import yaml
        spec_data = yaml.safe_load(spec_content)
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Error parsing YAML: {e}")

    if not isinstance(spec_data, dict):
        raise IRValidatorException("Parsed spec content is not a dictionary")

    required_fields = {'name', 'version', 'description'}
    missing_fields = required_fields - spec_data.keys()

    if missing_fields:
        raise IRValidatorException(f"Missing required fields: {', '.join(missing_fields)}")

    return spec_data

def validate_from_file(cls, yaml_file=None):
    import yaml
    from os.path import exists

    if yaml_file is None or not isinstance(yaml_file, str):
        raise ValueError("yaml_file must be a valid string path")

    if not exists(yaml_file):
        raise FileNotFoundError(f"The file {yaml_file} does not exist")

    try:
        with open(yaml_file, 'r') as file:
            data = yaml.safe_load(file)
    except yaml.YAMLError as e:
        raise ValueError(f"Error parsing YAML file: {e}")

    if not isinstance(data, dict):
        raise IRValidatorException("YAML file does not contain a dictionary")

    required_fields = {'name', 'version', 'description'}
    missing_fields = required_fields - data.keys()

    if missing_fields:
        raise IRValidatorException(f"Mandatory fields missing in YAML file: {missing_fields}")

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if not isinstance(parser_dict, dict):
        raise ValueError("parser_dict must be a dictionary")

    if 'include' not in parser_dict:
        return parser_dict

    include_directive = parser_dict['include']
    if not isinstance(include_directive, list):
        raise ValueError("The 'include' directive must be a list")

    for include_item in include_directive:
        if not isinstance(include_item, dict):
            raise ValueError("Each item in the 'include' list must be a dictionary")

        for key, value in include_item.items():
            if key in parser_dict and isinstance(parser_dict[key], dict) and isinstance(value, dict):
                parser_dict[key].update(value)
            else:
                parser_dict[key] = value

    del parser_dict['include']
    return parser_dict

