def _get_conditionally_required_args(self, command_name, options_spec, args):
    if not isinstance(command_name, str):
        raise ValueError("command_name must be a string")
    if not isinstance(options_spec, list):
        raise ValueError("options_spec must be a list")
    if not isinstance(args, dict):
        raise ValueError("args must be a dictionary")

    required_args = []

    for option in options_spec:
        if 'required_when' in option:
            condition = option['required_when']
            if isinstance(condition, dict):
                for cond_key, cond_value in condition.items():
                    if cond_key in args and args[cond_key] == cond_value:
                        required_args.append(option['name'])
            else:
                raise ValueError("required_when must be a dictionary")

    return required_args

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise ValueError("Arguments must be provided as a dictionary with keys as argument names and values as tuples of (value, max_length).")

    for arg_name, (value, max_length) in args.items():
        if not isinstance(value, str):
            raise ValueError(f"The value for argument '{arg_name}' must be a string.")
        if not isinstance(max_length, int) or max_length < 0:
            raise ValueError(f"The max_length for argument '{arg_name}' must be a non-negative integer.")
        if len(value) > max_length:
            raise ValueError(f"The value for argument '{arg_name}' is longer than the specified maximum length of {max_length}.")

